const SUPABASE_URL = 'https://pklriiaxigecpcfovevp.supabase.co';
const SERVICE_KEY = 'REDACTED';

const tables = [
  'vehicles', 'service_records', 'service_slips', 'fault_diagnoses',
  'maintenance_schedules', 'custom_intervals', 'insurance_policies',
  'puc_certificates', 'fastag_accounts', 'notifications',
  'notification_preferences', 'users'
];

const backup = {};

for (const table of tables) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/${table}?select=*`,
    headers: {
      apikey: SERVICE_KEY,
      Authorization: `Bearer ${SERVICE_KEY}`,
      Range: '0-9999'
    },
    json: true,
  });
  backup[table] = response;
}

backup._backup_metadata = {
  generated_at: new Date().toISOString(),
  table_count: tables.length
};

return [{ json: backup }];

