const KEY_ID = 'REDACTED';
const APPLICATION_KEY = 'REDACTED';
const BUCKET_ID = '312c4903ed628afca208051e';
const RETENTION_DAYS = 14;

const authString = Buffer.from(`${KEY_ID}:${APPLICATION_KEY}`).toString('base64');
const auth = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.backblazeb2.com/b2api/v2/b2_authorize_account',
  headers: { Authorization: `Basic ${authString}` },
  json: true,
});

const filesResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: `${auth.apiUrl}/b2api/v2/b2_list_file_names`,
  headers: { Authorization: auth.authorizationToken },
  body: { bucketId: BUCKET_ID, maxFileCount: 1000 },
  json: true,
});

const cutoff = Date.now() - RETENTION_DAYS * 24 * 60 * 60 * 1000;
const deleted = [];

for (const file of filesResponse.files) {
  if (file.uploadTimestamp < cutoff) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${auth.apiUrl}/b2api/v2/b2_delete_file_version`,
      headers: { Authorization: auth.authorizationToken },
      body: { fileName: file.fileName, fileId: file.fileId },
      json: true,
    });
    deleted.push(file.fileName);
  }
}

return [{ json: { deletedCount: deleted.length, deleted } }];
